  ('62373686-8084-5135-8511-dbef03d75e90', '22222222-2222-2222-2222-222222222204', 'mcq', '若“埃尔南德斯”或“墨菲”是卢森堡常见姓氏，则 “冈萨雷斯”是墨西哥常见姓氏。 根据以上信息，可以得出以下哪项?', '[{"key": "A", "text": "“施米特”是卢森堡常见姓氏。"}, {"key": "B", "text": "“埃尔南德斯”是卢森堡常见姓氏。"}, {"key": "C", "text": "“冈萨雷斯”是爱尔兰常见姓氏。"}, {"key": "D", "text": "“墨菲”是卢森堡常见姓氏。"}, {"key": "E", "text": "“墨菲”是阿根廷常见姓氏。 母题模型三 半事实假言推事实模型 （二）变式1：半事实假言推事实+匹配模 4配4"}]'::jsonb, '', '', '逻辑/基础必修5-综合推理1.pdf', 35, true, 22, null),
  ('11b92fd4-7c09-53be-a86a-7ccb353d22f2', '22222222-2222-2222-2222-222222222204', 'short', '埃卢∨墨卢→冈墨 情况一：施阿 施阿+（2）可得：冈兰 冈兰+（3）可得：¬埃卢∧¬墨卢 ¬施卢¬冈卢¬埃卢¬墨卢 卢森堡没有姓氏匹配，情况一为假 情况二：施卢 情况一为假，所以情况二为真 型 【例11】', null, 'A', '【第1步 识别命题形式】
