  ('f7ebdd1c-ec7b-587b-8e10-541a16cdffb9', '22222222-2222-2222-2222-222222222212', 'mcq', '当𝑥= −2 时，代数式𝑎𝑥5 + 𝑏𝑥3 + 𝑐𝑥−6 的值为8，则当𝑥= 2时， 代数式的值为( ).', '[{"key": "A", "text": "−8"}, {"key": "B", "text": "8"}, {"key": "C", "text": "12"}, {"key": "D", "text": "−12"}, {"key": "E", "text": "−20"}]'::jsonb, '', '', '数学/第2章 代数式  合订版.pdf', 20, true, 10, null),
  ('0de5b81b-9928-5c93-8225-07441177ed3e', '22222222-2222-2222-2222-222222222212', 'mcq', '的值是( ).', '[{"key": "A", "text": "1 2"}, {"key": "B", "text": "1 20"}, {"key": "C", "text": "1 10"}, {"key": "D", "text": "11 20"}, {"key": "E", "text": "1 15"}]'::jsonb, '', '', '数学/第2章 代数式  合订版.pdf', 22, true, 11, null),
  ('196bf1e6-fe58-5415-ab32-1e38e408c0ff', '22222222-2222-2222-2222-222222222213', 'mcq', '𝑥+ 𝑦+ 𝑧> 0 ⇒𝑥, 𝑦, 𝑧至少有一个大于0； 𝑥+ 𝑦+ 𝑧⩾0 ⇒𝑥, 𝑦, 𝑧至少有一个大于等于0. 6. 1 𝑛(𝑛+𝑘) = 1 𝑘( 1 𝑛− 1 𝑛+𝑘) ， 1 √𝑛+𝑘−√𝑛= 1 𝑘(√𝑛+ 𝑘+ √𝑛). 知新 主讲人：十一老师 现在是网络设备测试时间，课程将准时开始，请大家耐心等待 你的坚持，终将美好！ 16 题型1：考查乘积的裂项 例1： 1 1×2 + 1 2×3 + 1 3×4 + ⋯+ 1 99×100 = ( ).', '[{"key": "A", "text": "99 100"}, {"key": "B", "text": "100 101"}, {"key": "C", "text": "99 101"}, {"key": "D", "text": "97 100"}, {"key": "E", "text": "98 100 题型2：考查根式的裂项 例2： 1 1+√2 + 1 √2+√3 + 1 √3+√4 + ⋯+ 1 √99+√100 = ( )."}, {"key": "A", "text": "9"}, {"key": "B", "text": "10"}, {"key": "C", "text": "11"}, {"key": "D", "text": "3√11 −1"}, {"key": "E", "text": "3√11 你的坚持，终将美好！ 17 你的坚持，终将美好！ 18 题型3：考查分式的裂项"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 1, true, 1, null),
  ('42b93742-c070-5c66-982b-bfa3bff78e00', '22222222-2222-2222-2222-222222222213', 'mcq', '𝑓(𝑥) = 1 (𝑥+1)(𝑥+2) + 1 (𝑥+2)(𝑥+3) + ⋯+ 1 (𝑥+9)(𝑥+10) , 𝑓(8) = ( ).', '[{"key": "A", "text": "1 9"}, {"key": "B", "text": "1 10"}, {"key": "C", "text": "1 16"}, {"key": "D", "text": "1 17"}, {"key": "E", "text": "1 18 你的坚持，终将美好！ 19 知识咖啡站：（此为自学部分，学有余力的同学自行查看） 一、𝒏次方公式"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 4, true, 2, null),
  ('85e51503-7aad-59f4-833f-6292daa46847', '22222222-2222-2222-2222-222222222213', 'mcq', '已知𝐴= {𝑎+ 2, (𝑎+ 1)2, 𝑎2 + 3𝑎+ 3}，若1 ∈𝐴，求实数𝑎的值( ).', '[{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}, {"key": "E", "text": "0"}]'::jsonb, '', '', '数学/第3章 集合与函数（1）合订版.pdf', 10, true, 3, null),
