  ('b60db6cd-16ff-51d8-92f3-98a64dcddfae', '22222222-2222-2222-2222-222222222213', 'mcq', '如果函数𝑓(𝑥) = (1 −2𝑎)𝑥在实数集𝐑上是减函数，那么实数𝑎的取值 范围是( ).', '[{"key": "A", "text": "(0, 1 2)"}, {"key": "B", "text": "(1 2 , +∞)"}, {"key": "C", "text": "(−∞, 1 2)"}, {"key": "D", "text": "(−1 2 , 1 2)"}, {"key": "E", "text": "(1, +∞)"}]'::jsonb, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 5, true, 15, null),
  ('34275d33-7afa-519f-840e-c086f41f8967', '22222222-2222-2222-2222-222222222213', 'mcq', '已知函数𝑓(𝑥) = 5𝑥，若𝑓(𝑎+ 𝑏) = 3，则𝑓(2𝑎)𝑓(2𝑏) = ( ).', '[{"key": "A", "text": "3"}, {"key": "B", "text": "4"}, {"key": "C", "text": "5"}, {"key": "D", "text": "9"}, {"key": "E", "text": "25"}]'::jsonb, '', '', '数学/第3章 集合与函数（2）含解析的合订版.pdf', 5, true, 16, null),
