  ('dbbaf6f5-9f9f-52b2-a848-ab5cd211a127', '22222222-2222-2222-2222-222222222216', 'mcq', '已知船在静水中的速度为25 千米/小时，水流的速度为15 千米/小时， 则此船在相距80 千米的两地间往返一次所需要的时间是( )小时.', '[{"key": "A", "text": "8"}, {"key": "B", "text": "10"}, {"key": "C", "text": "12"}, {"key": "D", "text": "14"}, {"key": "E", "text": "16"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 13, null),
  ('ddd3a83c-0a05-5e6b-b4ac-18ac282447a6', '22222222-2222-2222-2222-222222222216', 'mcq', '一列火车长75 米，通过525 米长的桥梁需要40 秒，若以同样的速度 穿过300 米的隧道，则需要( )秒.', '[{"key": "A", "text": "20"}, {"key": "B", "text": "23"}, {"key": "C", "text": "25"}, {"key": "D", "text": "27"}, {"key": "E", "text": "28"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 25, true, 14, null),
  ('dc1af061-4140-5a4e-9b3d-6aa55f8befaf', '22222222-2222-2222-2222-222222222216', 'mcq', '货车行驶72km用时1h，其速度𝑣与行驶时间𝑡的关系如图所示，则𝑣0 = ( )km/h.', '[{"key": "A", "text": "72"}, {"key": "B", "text": "80"}, {"key": "C", "text": "90"}, {"key": "D", "text": "95"}, {"key": "E", "text": "100"}]'::jsonb, '', '', '数学/第6章 应用题(1) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 26, true, 15, null),
  ('3ce7238a-7577-51cc-8664-c63811277387', '22222222-2222-2222-2222-222222222216', 'mcq', '一项工程甲、乙、丙三人合作需要15 天完成，如果乙休息2 天，丙就 要多做4 天，或者由甲、乙两人合作1 天，则这项工程由丙单独做需要 ( )天.', '[{"key": "A", "text": "40"}, {"key": "B", "text": "45"}, {"key": "C", "text": "50"}, {"key": "D", "text": "60"}, {"key": "E", "text": "75"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 16, null),
  ('5daaf729-36b6-5274-b007-759c6b4b3cde', '22222222-2222-2222-2222-222222222216', 'mcq', '某工程由甲公司承包需要60 天完成，由甲、乙两公司共同承包需要28 天完成，由乙、丙两公司共同承包需要35 天完成，则由丙公司承包完 成该工程需要的天数为( ).', '[{"key": "A", "text": "85"}, {"key": "B", "text": "90"}, {"key": "C", "text": "95"}, {"key": "D", "text": "10"}, {"key": "E", "text": "105"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 17, null),
  ('dc046df9-6287-539a-8674-08c82f6644f6', '22222222-2222-2222-2222-222222222216', 'mcq', '完成某项任务，甲单独做需要12 天，乙单独做需要6 天，丙单独做需 要24 天，现甲、乙、丙三人依次一日一轮地工作，则完成该项任务共 需的天数为( ).', '[{"key": "A", "text": "9 3 4"}, {"key": "B", "text": "10 1 4"}, {"key": "C", "text": "10 3 4"}, {"key": "D", "text": "10"}, {"key": "E", "text": "11 1 4 你的坚持，终将美好！ 23 你的坚持，终将美好！ 24 三、牛吃草公式 𝑦= (𝑁−𝑥) × 𝑇"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 18, null),
  ('aef17324-af63-5a5d-a0ac-710c913102c9', '22222222-2222-2222-2222-222222222216', 'mcq', '牧场上一片青草，每天牧草都均匀生长。这片牧草可供100 头牛吃20 天，或者可供150 头牛吃10 天。则这片牧场可供250 头牛吃( )天.', '[{"key": "A", "text": "5"}, {"key": "B", "text": "6"}, {"key": "C", "text": "7"}, {"key": "D", "text": "8"}, {"key": "E", "text": "9"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 8, true, 19, null),
  ('62761a14-ee65-5dfb-b317-fe30b5456235', '22222222-2222-2222-2222-222222222216', 'mcq', '某道路一侧原有路灯106 盏，道路两端均设有路灯，相邻两盏灯的距 离为36m，现将原有路灯全部换为新型节能灯，两灯距离变为70m， 道路两端依旧各装一盏路灯，布局不超出原道路范围，则道路一侧共需 新型节能灯( )盏.', '[{"key": "A", "text": "54"}, {"key": "B", "text": "55"}, {"key": "C", "text": "108"}, {"key": "D", "text": "110"}, {"key": "E", "text": "112"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 10, true, 20, null),
  ('b7f97ffd-8fcd-5748-8c5d-c5a28ee3ecc2', '22222222-2222-2222-2222-222222222216', 'mcq', '将一批树苗种在一个正方形花园的边上，四角都种.如果每隔3m 种一 棵，那么剩下10 棵树苗；如果每隔2m 种一棵，那么恰好种满正方形 的3 条边，则这批树苗有( )棵.', '[{"key": "A", "text": "54"}, {"key": "B", "text": "60"}, {"key": "C", "text": "70"}, {"key": "D", "text": "82"}, {"key": "E", "text": "94"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 10, true, 21, null),
  ('54a5d821-1632-5af2-8beb-aadef8c43c68', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位有职工40 人，其中参加计算机考核的有31 人，参加外语考核 的有20 人，有8 人没有参加任何一种考核，则同时参加两项考核的职 工有( )人.', '[{"key": "A", "text": "10"}, {"key": "B", "text": "13"}, {"key": "C", "text": "15"}, {"key": "D", "text": "19"}, {"key": "E", "text": "20"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 22, null),
  ('1ad39b13-56ac-5a32-b819-c3af32d6f9cd', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位有240 名员工，其中订阅𝐴期刊的有125 人，订阅𝐵期刊的有 126 人，订阅𝐶期刊的有135 人，订阅𝐴、𝐵期刊的有57 人，订阅𝐴、𝐶 期刊的有73 人，订阅3 种期刊的有31 人，此外，还有17 人没有订 阅这三种期刊中的任何一种。则订阅𝐵、𝐶期刊的有( )人.', '[{"key": "A", "text": "57"}, {"key": "B", "text": "64"}, {"key": "C", "text": "69"}, {"key": "D", "text": "78"}, {"key": "E", "text": "81"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 13, true, 23, null),
  ('ccc90b4a-6153-5eab-96f9-1fd203d8b608', '22222222-2222-2222-2222-222222222216', 'mcq', '某公司的员工中，拥有本科毕业证、计算机等级证、汽车驾驶证的人数 分别为130，110，90，又知只有一种证的人数为140，三证齐全的人 数为30，则恰有双证的人数为( ).', '[{"key": "A", "text": "45"}, {"key": "B", "text": "50"}, {"key": "C", "text": "52"}, {"key": "D", "text": "65"}, {"key": "E", "text": "100"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 14, true, 24, null),
  ('ddd795b2-79c0-5209-8ce4-fa290320cd38', '22222222-2222-2222-2222-222222222216', 'mcq', '某公司用1 万元购买了价格分别是1750 元和950 元的甲、乙两种办 公设备，则购买的甲、乙办公设备的件数分别为( ).', '[{"key": "A", "text": "3,5"}, {"key": "B", "text": "5,3"}, {"key": "C", "text": "4,4"}, {"key": "D", "text": "2,6"}, {"key": "E", "text": "6,2"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 25, null),
  ('fb0bf2ea-4ba5-58e7-acb5-b2e4049d6e70', '22222222-2222-2222-2222-222222222216', 'mcq', '某单位向希望工程捐款，其中部门领导每人捐50 元，普通员工每人捐 20 元，某部门所有人员共捐款320 元，已知该部门总人数超过10 人， 则该部门可能有( )名部门领导.', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 26, null),
  ('e5d10754-0933-5154-bfe5-37c7381d7bdf', '22222222-2222-2222-2222-222222222216', 'mcq', '有271 位游客欲乘大、小两种客车旅游，已知大客车有37 个座位，小 客车有20 个座位. 为保证每位游客均有座位，且车上没有空座位，则 需要大客车的辆数是( ).', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "3"}, {"key": "D", "text": "4"}, {"key": "E", "text": "5"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 27, null),
  ('877caa3c-4a38-5131-8d32-369f935db711', '22222222-2222-2222-2222-222222222216', 'mcq', '某自来水公司的水费计算方法如下：每户每月用水不超过5 吨的，每 吨收费4 元，超过5 吨的，每吨收取较高标准的费用.已知9 月份张家 的用水量比李家的用水量多50%，张家和李家的水费分别是90 元和 55 元，则用水量超过5 吨的收费标准是( )元/吨.', '[{"key": "A", "text": "5"}, {"key": "B", "text": "5.5"}, {"key": "C", "text": "6"}, {"key": "D", "text": "6.5"}, {"key": "E", "text": "7"}]'::jsonb, '', '', '数学/第6章 应用题(2) 含解析的合订版（适合使用在线文档查看的同学）.pdf', 19, true, 28, null),
