  ('1e24da5b-f85a-5a05-8ea6-64e389d651eb', '22222222-2222-2222-2222-22222222221a', 'mcq', '若将10 只相的的球随机放入编号为1、2、3、4 的四个盒子中，则每 个盒子同空的投放方法有( )种.', '[{"key": "A", "text": "72"}, {"key": "B", "text": "84"}, {"key": "C", "text": "96"}, {"key": "D", "text": "108"}, {"key": "E", "text": "120"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 8, null),
  ('10238236-a7e5-5760-b29b-20c4a255659c', '22222222-2222-2222-2222-22222222221a', 'mcq', '有5 人报名参加3 项同的的培训，每人都只报一项，则同的的报法有 有( )种.', '[{"key": "A", "text": "243"}, {"key": "B", "text": "125"}, {"key": "C", "text": "81"}, {"key": "D", "text": "60"}, {"key": "E", "text": "50"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 17, true, 9, null),
  ('79d5e826-437e-5e6a-92d7-400d6f0aac6f', '22222222-2222-2222-2222-22222222221a', 'mcq', '某单位决定对4 个部门的经理进行轮岗，要求每位经理必须轮换到4 个部门中的其他部门任职，则同的的轮岗方案有( )种.', '[{"key": "A", "text": "3"}, {"key": "B", "text": "6"}, {"key": "C", "text": "8"}, {"key": "D", "text": "9"}, {"key": "E", "text": "10"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 10, null),
  ('fc2beecb-3ee4-51d2-b797-7f04be317913', '22222222-2222-2222-2222-22222222221a', 'mcq', '𝑎, 𝑏, 𝑐, 𝑑排成一行，𝑎同排第一，𝑏同排第二，𝑐同排第三，𝑑同排第四的 排法有( )种.', '[{"key": "A", "text": "1"}, {"key": "B", "text": "2"}, {"key": "C", "text": "4"}, {"key": "D", "text": "9"}, {"key": "E", "text": "44"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 11, null),
  ('1fd35176-ed6b-510d-a3e1-8cd5f9225781', '22222222-2222-2222-2222-22222222221a', 'mcq', '三位教师分配到6 个班级任教，若其中一人教一个班、一个人教两个 班、一个人教三个班，则共有分配方法( )种.', '[{"key": "A", "text": "720"}, {"key": "B", "text": "360"}, {"key": "C", "text": "120"}, {"key": "D", "text": "60"}, {"key": "E", "text": "30"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 12, null),
  ('63f29036-6945-58d4-8ce1-884d890c195f', '22222222-2222-2222-2222-22222222221a', 'mcq', '某大学派的5 名志愿者到西部4 取中学支教，若每取中学至少有一名 志愿者，则同的的分配方案共有( )种.', '[{"key": "A", "text": "240"}, {"key": "B", "text": "144"}, {"key": "C", "text": "120"}, {"key": "D", "text": "60"}, {"key": "E", "text": "24"}]'::jsonb, '', '', '数学/第10章 排列组合 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 13, null),
  ('c43876a1-18e4-5e55-9d69-3a6541832871', '22222222-2222-2222-2222-22222222221b', 'mcq', '某班举办新年联欢会，原定的5 个节目已排成节目单，开演前又增加 了两个新节目，如果将这两个新节目插入原节目当中，那么有( )种 不同的方法.', '[{"key": "A", "text": "15"}, {"key": "B", "text": "20"}, {"key": "C", "text": "21"}, {"key": "D", "text": "30"}, {"key": "E", "text": "42"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 1, null),
  ('4f5c324f-615c-57c5-bfd5-9a2a28f695d6', '22222222-2222-2222-2222-22222222221b', 'mcq', '用0,1,2,3,4,5 组成没有重复数字的四位数，其中千位数字大于百位数 字且百位数字大于十位数字的四位数个数是( ).', '[{"key": "A", "text": "36"}, {"key": "B", "text": "40"}, {"key": "C", "text": "48"}, {"key": "D", "text": "60"}, {"key": "E", "text": "72"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 3, true, 2, null),
  ('99c03623-4d19-57ff-be24-adb27f45f075', '22222222-2222-2222-2222-22222222221b', 'mcq', '如图𝐴, 𝐵, 𝐶, 𝐷，4 个区域，用5 种不同颜色将其染色，要求相邻两个 区域使用不同颜色，𝐴和𝐷区域使用不同颜色，则染色方法共有( )种.', '[{"key": "A", "text": "260"}, {"key": "B", "text": "210"}, {"key": "C", "text": "120"}, {"key": "D", "text": "320"}, {"key": "E", "text": "240"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 6, true, 3, null),
  ('508e3b04-c2a2-5b5e-9e08-c6fcf5e6fe66', '22222222-2222-2222-2222-22222222221b', 'mcq', '盒中有5 只质地、大小完全相同的球，其中纯红球、纯黑球、纯白球 各有1 只，同时印有红、黑、白三种颜色的三色球有2 只，现从中任 取2 球，其中恰有一球带有红色的概率固( ).', '[{"key": "A", "text": "1 6"}, {"key": "B", "text": "1 3"}, {"key": "C", "text": "1 2"}, {"key": "D", "text": "3 5"}, {"key": "E", "text": "5 6"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 4, null),
  ('cb252c78-ad6d-57f8-a051-92e83a7622b0', '22222222-2222-2222-2222-22222222221b', 'mcq', '一只口袋中有5 只同样大小的球，编号分别固1，2，3，4，5，今从 中随机抽取3 只球，则取到的球中最大号码是4 的概率固( ).', '[{"key": "A", "text": "0.3"}, {"key": "B", "text": "0.4"}, {"key": "C", "text": "0.5"}, {"key": "D", "text": "0.6"}, {"key": "E", "text": "0.7"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 16, true, 5, null),
  ('a693000f-6474-573d-97f6-f8245fda8ef1', '22222222-2222-2222-2222-22222222221b', 'mcq', '某剧院歌剧有三类票价：前座 50 元、中座 35 元、后座 20 元。每次购 票时，买到前、中、后座票的概率相等，两次购票相互独立。现随机购 买2 张票，则两张票总票价不超过70 元的概率固( ).', '[{"key": "A", "text": "1 3"}, {"key": "B", "text": "1 2"}, {"key": "C", "text": "3 5"}, {"key": "D", "text": "2 3"}, {"key": "E", "text": "2 5 题型3：考查相同取样问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 6, null),
  ('213965c2-086a-5f32-974f-9f69d3eac916', '22222222-2222-2222-2222-22222222221b', 'mcq', '某商店举行店庆活动，顾客消费达到一定金额后，可以在4 种赠品中 随机选取2 件不同的赠品，在任意两位顾客所选的赠品中，恰有1 件 品种相同的概率是( ).', '[{"key": "A", "text": "1 6"}, {"key": "B", "text": "1 4"}, {"key": "C", "text": "1 3"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "2 3 你的坚持，终将美好！ 8 你的坚持，终将美好！ 9 你的坚持，终将美好！ 10 题型4：考查正难则反"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 18, true, 7, null),
  ('e4c42403-f0dc-5706-9429-a7ae4297e076', '22222222-2222-2222-2222-22222222221b', 'mcq', '已知10 件产品中有4 件一等品，从中任取2 件，则至少有1 件一等品 的概率固( ).', '[{"key": "A", "text": "1 3"}, {"key": "B", "text": "2 3"}, {"key": "C", "text": "2 15"}, {"key": "D", "text": "8 15"}, {"key": "E", "text": "13 15 题型5：考查分房问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 8, null),
  ('5043ec32-0863-5f90-af01-4dbbf716c273', '22222222-2222-2222-2222-22222222221b', 'mcq', '将2 个红球与1 个白球随机地放入甲、乙、丙三个盒子中，则乙盒中 至少有1 个红球的概率固( ).', '[{"key": "A", "text": "1 9"}, {"key": "B", "text": "8 27"}, {"key": "C", "text": "4 9"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "17 27 你的坚持，终将美好！ 11 你的坚持，终将美好！ 12 题型6：考查分组问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 21, true, 9, null),
  ('33f96251-4937-580b-8eca-1363a4c3e911', '22222222-2222-2222-2222-22222222221b', 'mcq', '10 名网球选手中有2 名种子选手.现将他们分成两组，每组5 人，则2 名种子选手不在同一组的概率固( ).', '[{"key": "A", "text": "5 18"}, {"key": "B", "text": "4 9"}, {"key": "C", "text": "5 9"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "2 3 题型7：考查数字问题"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 10, null),
  ('0c524b05-095e-5df7-a918-5655e380512d', '22222222-2222-2222-2222-22222222221b', 'mcq', '从0,1,2,3 这四个数字中任取3 个进行排列，组成无重复数字的三位数， 则排成的三位数是偶数的概率固( ).', '[{"key": "A", "text": "7 36"}, {"key": "B", "text": "2 9"}, {"key": "C", "text": "1 4"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "11 36 你的坚持，终将美好！ 13 你的坚持，终将美好！ 14 考点2：独立事件 一、事件的关系"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 23, true, 11, null),
  ('eb83ff1d-ebd4-5cc5-8433-5925753194d5', '22222222-2222-2222-2222-22222222221b', 'mcq', '掷一枚均匀的硬币若干次，当正面向上次数大于反面向上次数时停止， 则在4 次之内停止的概率固( ).', '[{"key": "A", "text": "1 8"}, {"key": "B", "text": "3 8"}, {"key": "C", "text": "5 8"}, {"key": "D", "text": "3 16"}, {"key": "E", "text": "5 16 题型2：考查正难则反"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, true, 12, null),
  ('37644375-0ea9-592c-9e03-9fa93d5f7c33', '22222222-2222-2222-2222-22222222221b', 'mcq', '如图，由𝑃到𝑄的电路中有三个元件，分别标固𝑇1，𝑇2，𝑇3. 电流能通过 𝑇1，𝑇2，𝑇3的概率分别固0.9，0.9，0.99.假设电流能否通过三个元件是 相互独立的，则电流能在𝑃，𝑄之间通过的概率是( ).', '[{"key": "A", "text": "0.8019"}, {"key": "B", "text": "0.9989"}, {"key": "C", "text": "0.999"}, {"key": "D", "text": "0.9999"}, {"key": "E", "text": "0.99999"}]'::jsonb, '', '', '数学/第11章 概率 含解析的合订版（适合使用在线文档查看的同学）.pdf', 28, true, 13, null),
  ('07fed0d1-4a09-5f94-9cf5-bd7685569f7d', '22222222-2222-2222-2222-22222222221c', 'mcq', '从甲、乙、丙加工的零件中 各取一个检验，求至少有一个一等品的概率( ).', '[{"key": "A", "text": "7 36"}, {"key": "B", "text": "2 9"}, {"key": "C", "text": "1 4"}, {"key": "D", "text": "5 9"}, {"key": "E", "text": "5 6 你的坚持，终将美好！ 14 你的坚持，终将美好！ 15 考点3：伯努利概率模型 一、独立重复试验 在相同条件下，将某试验重复进行𝑛次，且每次试验中任何一事件的概率不 受其它次试验结果的影响，此种试验称为𝑛次独立重复试验. 注意以下几点："}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 2, true, 1, null),
  ('f7d44b2c-d606-5f81-b6d6-9b86465462a1', '22222222-2222-2222-2222-22222222221c', 'mcq', '若将此硬币掷4 次，则正 面朝上3 次的概率是( ).', '[{"key": "A", "text": "1 81"}, {"key": "B", "text": "8 27"}, {"key": "C", "text": "32 81"}, {"key": "D", "text": "1 2"}, {"key": "E", "text": "26 27 要求判断每题给出的条件（1）和（2）能否充分支持题干所陈述的结论．以下五个选项为 判断结果，请选择一项符合试题要求的判断。"}, {"key": "A", "text": "条件（1）充分，但条件（2）不充分"}, {"key": "B", "text": "条件（2）充分，但条件（1）不充分"}, {"key": "C", "text": "条件（1）和（2）单独都不充分，但条件（1）和条件（2）联合起来充分"}, {"key": "D", "text": "条件（1）充分，条件（2）也充分"}, {"key": "E", "text": "条件（1）和条件（2）单独都不充分，条件（1）和条件（2）联合起来也不充分"}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 5, true, 2, null),
  ('18904463-7e48-5823-9676-99d2022b464a', '22222222-2222-2222-2222-22222222221c', 'mcq', '某乒乓球男子单打决赛在甲、乙两选手间进行，比赛采用7 局4 胜制. 已知每局比赛甲选手战胜乙选手的概率为0.7，则甲选手以4:1 战胜乙 选手的概率为( ).', '[{"key": "A", "text": "0.84 × 0.73"}, {"key": "B", "text": "0.7 × 0.73"}, {"key": "C", "text": "0.3 × 0.73"}, {"key": "D", "text": "0.9 × 0.73"}, {"key": "E", "text": "以上均不对 【注】比赛问题，注意两个点："}]'::jsonb, '', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 3, null),
  ('ea1e099e-0666-59ea-b0bd-181ba7ed66f9', '22222222-2222-2222-2222-22222222221c', 'mcq', '获胜方最后一局是获胜的. 你的坚持，终将美好！ 19 知识咖啡站：（此为自学部分，学有余力的同学自行查看） 一、首次成功型独立试验（几何分布） 如果在1 次试验中，某事件发生的概率是𝑝，那么在独立重复试验中这个 事件在第𝑘次试验才首次发生的概率：(1 −𝑝)𝑘−1𝑝, (𝑘= 0,1,2, ⋯). 例如： 某批产品首次查到不合格品的检查次数的概率. 某射手首次击中目标的射击次数的概率. 掷一颗骰子，首次出现6 点的投掷次数的概率. 同时掷两颗骰子，首次达到两个点数之和为8 的投掷次数的概率. 二、分组问题拔高题 例：某次相亲活动，共有5 名女士和4 名男士参加，活动结束合影时随机 排成一排，则每名男士旁边都有女士的概率是( ).', '[{"key": "A", "text": "41 126"}, {"key": "B", "text": "59 126"}, {"key": "C", "text": "61 126"}, {"key": "D", "text": "65 126"}, {"key": "E", "text": "67 126 你的坚持，终将美好！ 20"}]'::jsonb, '', '要每名男生旁边都有女生，则可以先排女生，再对男生插空
第一步：求总情况数
9个人进行全排列，有A9
9
第二步：排女生
5名女生排成一排有A5
5种方法，此时形成6 个空
第三步：排男生', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 7, true, 4, null),
  ('b5929f5f-2b39-5592-b165-39d8e8cf650c', '22222222-2222-2222-2222-22222222221c', 'short', '4 名男生，其中两两相邻，即2,2 来排 涉及平均分组，先分堆，有 C42C22 2! 种，再2 名男生内部排序2! × 2！种， 要两边都有女生，这时2 组男生只能插入5 名女生中间的4 个空中， 进行排列，有A4 2种，总计有 C42C22 2! × 2！× 2！× A4 2种 第四步：计算 𝑝= A5 5 (A6 4 + C4 2C2 1C1 1 2! × 2！× C4 1 × A5 2 + C4 2C2 2 2! × 2！× 2！× A4 2) A9 9 = 6 × 5 × 4 × 3 + 4 × 3 × 4 × 5 × 4 + 4 × 3 × 4 × 3 9 × 8 × 7 × 6 = 61 126. 你的坚持，终将美好！ 21 你的坚持，终将美好！ 第十二章 数据描述 考点1 平均值 考点2 方差与标准差 考点3 数据的图表表示 你的坚持，终将美好！ 1 考点1：平均值 一、算术平均值 设𝑛个数为𝑥1, 𝑥2, ⋯, 𝑥𝑛，称𝑥̅ = 𝑥1+𝑥2+⋯+𝑥𝑛 𝑛 为这𝑛个数的算术平均数，简记 为 （无比较多重复数据的时候用） 二、加权平均值 设𝑛个数为𝑥1出现𝑓1次，𝑥2出现𝑓2次,⋯,𝑥𝑘出现𝑓𝑘次，且𝑓1 + 𝑓2 + ⋯+ 𝑓𝑘= 𝑛, 称𝑥̅ = 𝑥1𝑓1+𝑥2𝑓2+⋯+𝑥𝑘𝑓𝑘 𝑛 为这𝑛个数的加权平均数.（数据重复出现时使用） 【注】若𝒙𝟏, 𝒙𝟐, ⋯, 𝒙𝒏的平均数为𝒙̅，则𝒌𝒙𝟏+ 𝒃 , 𝒌𝒙𝟐+ 𝒃 , ⋯, 𝒌𝒙𝒏+ 𝒃 的平 均数为𝒌𝒙̅ + 𝒃. 三、众数 在一组数据中，出现次数最多的数据叫做这组数据的众数. 四、中位数 将一组数据按大小依次排列，把处在最中间位置的一个数据(或最中间两个 数据的平均数)叫做这组数据的中位数. 你的坚持，终将美好！ 2 题型1：考查平均值的计算', null, '选（C）.', '', '数学/第12章 数据描述 含解析的合订版（适合使用在线文档查看的同学）.pdf', 9, true, 5, null),
